-- 2) 7 zonas Previfoc PROVISIONALES: CV intersecada con bandas latitudinales.
--    ST_CollectionExtract(...,3) conserva solo polígonos. Recorte a la forma de la CV.
insert into territorios (id, codigo, padre_id, nivel, nombre, geom)
select
  gen_random_uuid(),
  'CV-PREF-Z' || z,
  cv.id,
  'zona_pref',
  'Zona ' || z || ' Previfoc (PROVISIONAL - geometría no oficial)',
  ST_Multi(ST_CollectionExtract(
    ST_Intersection(
      cv.geom,
      ST_SetSRID(ST_MakeEnvelope(-1.7, 37.84 + (z-1)*(40.79-37.84)/7.0,
                                  0.9, 37.84 +  z   *(40.79-37.84)/7.0), 4326)
    ), 3))
from (select id, geom from territorios where codigo = 'CV') cv,
     generate_series(1, 7) as z
on conflict (codigo) where codigo is not null do nothing;

-- 3) Auto-verificación del espacial en el servidor: si el punto de Castelló
--    (-0.0513, 39.9864) no cae dentro de la CV, aborta el push. Verifica que la
--    geometría oficial y ST_Contains funcionan de verdad en PostGIS.
do $$
begin
  if not exists (
    select 1 from territorios
    where codigo = 'CV'
      and ST_Contains(geom, ST_SetSRID(ST_MakePoint(-0.0513, 39.9864), 4326))
  ) then
    raise exception 'Sanity check fallo: el punto de Castello no cae dentro de la CV';
  end if;
  raise notice 'Sanity check OK: Castello cae dentro de la Comunitat Valenciana.';
end $$;
